\begin{theorem}\label{thmmane}
Let $M$ be a closed manifold. Let $L\colon TM\longrightarrow \R$ be a Tonelli Lagrangian and let $V\in C^2(M)$ be such that  $\max_M V = 0$. Then:
\begin{enumerate}[label=\textbf{(\roman*)},ref=(\roman*)]
\item\label{Mane point 1} We have $\beta_{L_V}(h) \leq  \beta_{L}(h)$ for every $h\in H_1(M;\R)$.
\item\label{Mane point 2} Let $h\in H_1(M;\R)\setminus\{0\}$. Then:
{\begin{equation*}
\beta_{L_V}(h) =  \beta_{L}(h) \quad \Longleftrightarrow\quad
{ \mathfrak M}_{L}^h \subseteq  { \mathfrak M}_{L_V}^h 
\;\; \text{and} \;\;
V \equiv 0 \;\; \text{on}  \;\; \widetilde { \mathcal M}_{L}^h \subseteq \widetilde { \mathcal M}_{L_V}^h.
\end{equation*}
}
\item\label{Mane point 3} Let $M=\T^n$ and $L(x,v)=\ell(v)$, i.e., it is a completely integrable system. Let $h\in H_1(M;\R)\setminus\{0\}$. Then, considering $\ell_V:=\ell+V$:
{ \begin{equation*}
\beta_{\ell_V}(h) =  \beta_{\ell}(h) \quad \Longleftrightarrow\quad
V \equiv 0 \;\; \text{on}  \;\; M.
\end{equation*}
}
\end{enumerate}

\end{theorem}

ref_dict.maincordim2:
\begin{corollary} \label{maincordim2}
Let $g$ be a Riemannian metric on $\T^2$ and let $g_0$ its normalized conformally equivalent flat metric. Then, $\beta_g(h) \leq \beta_{g_0}(h)$ for every $h\in H_1(\T^2;\R)$. Moreover, equality holds at some  $h\in H_1(\T^2;\R)\setminus \{0\}$ if and only if $g = g_0$, i.e., $g$ is flat.
\end{corollary}

ref_dict.thm_bangert:
\begin{theorem}[Bangert]\label{thm_bangert}
	Suppose a Riemannian metric $g$ on the $2$-torus $\T^2$ has the same stable norm or Mather's $\beta$-function as a flat metric $g_0$ on $\T^2$. Then, $(\T^2, g)$ and $(\T^2, g_0)$ are isometric by an isometry homotopic to the identity.
\end{theorem}

