\label{thm:main}
Let $(\theta_n)$ be i.i.d. random variables on $[0,2\pi)$ satisfying \eqref{eqn:Nunidimensional}, and $(S_n, n \geq 1)$ the ERW defined by \eqref{eqn:defERWC}.
\begin{itemize}
  \item If $\Re(\Phi_1) < 1/2$, then writing $\sigma^2 = \frac{1}{1 - 2 \Re(\Phi_1)} \in (1/3,\infty)$, we have
  \begin{equation}
   \label{eqn:mainSub}
    \lim_{n \to \infty} \frac{S_n}{n^{1/2}} = \mathcal{N}_\mathbb{C}(0,\sigma^2) \quad \text{ in law}.
  \end{equation}
  \item If $\Re(\Phi_1)= 1/2$, then
  \begin{equation}
    \label{eqn:mainCrit}
    \lim_{n \to \infty} \frac{S_n}{(n \log n)^{1/2}} = \mathcal{N}_\mathbb{C}(0, 1)\quad \text{ in law}.
  \end{equation}
  \item If $\Re(\Phi_1)> 1/2$, there exists a $\mathbb{C}$-valued random variable $W$ such that, writing $\sigma^2 =\frac{1}{2 \Re(\Phi_1) - 1} \in(1,\infty)$, we have
  \begin{equation}
    \label{eqn:mainSup}
    \lim_{n \to \infty} S_n\mathrm{e}^{- \Phi_1 \log n} = W \quad \text{a.s. \quad and} \quad \lim_{n \to \infty} \frac{S_n  - \mathrm{e}^{\Phi_1 \log n} W}{n^{1/2}} = \mathcal{N}_\mathbb{C}(0,\sigma^2) \quad \text{ in law}.
  \end{equation}
\end{itemize}

