theorem.content:
\label{equiv.ABP}
There is a $C_2$-equivariant map of spectra with $C_2$-action,
\begin{equation}\label{Real.ABP.map}
F^c_{\RR} : (\MSpin^c_{\RR})^e \xrightarrow{\big(\bigvee_I f^I_{\RR} \big)\times\big(\bigvee_z f^z_{\RR}\big)} \bigvee_{I \in \mathcal{P}} \ku_{\RR} \langle 4|I| \rangle^e \vee \bigvee_{z \in Z} \Sigma^{|z|}\HZmod,
\end{equation}
whose underlying spectrum map is the 2-local splitting of $\MSpin^c$ of Anderson--Brown--Peterson \cite{ABPspin67} and Stong \cite{Stong68}.

ref_dict.cor.homotopy.groups:
\begin{corollary}[Theorem \ref{thm.HFP.groups}]\label{cor.homotopy.groups}
     There exists an isomorphism of abelian groups,
     $$
     \begin{aligned}
     \pi_*((\MSpinR)^{hC_2}) &\cong \pi_*\big(\bigvee_{I}\kuRangle{4|I|}^{hC_2} \vee \bigvee_{z \in Z} \Sigma^{|z|}\HZmod^{hC_2}\big) \\
     &\cong \bigoplus_{I \in \mathcal{P}} (\pi_*\ko\langle 4 |I| \rangle \oplus \bigoplus_{m\geq1} \mathbb{Z}/2\{\delta^m_I\}) \oplus \bigoplus_{z \in Z, n \geq 1} \Z2\{w^n_z\}, 
     \end{aligned}
     $$
    where  $|\delta^m_I| = 4|I| - 4m$ when $|I|$ is even,  $|\delta^m_I| = 4|I| - 2 - 4m$ when $|I|$ is odd, and $|w^n_z| = |z| - n$.
\end{corollary}

ref_dict.cor.homotopy.fixedpoints:
\begin{corollary}[Theorem \ref{homotopy.fixedpoints}]\label{cor.homotopy.fixedpoints}
The Anderson--Brown--Peterson map \eqref{Real.ABP.map} induces a 2-local equivalence, 
$$
(\MSpinR)^{hC_2} \to \bigvee_{I \in \mathcal{P}}\kuRangle{4|I|}^{hC_2} \vee \bigvee_{z \in Z}\Sigma^{|z|}\HZmod^{hC_2}.
$$
\end{corollary}

